// ===== rk_galui_v2: "Galerija" valdymo skydelis (paprastas klientui, modernus) =====
add_action('init', function () {
    register_term_meta('rk_gal_kat', 'rk_page', array('type' => 'integer', 'single' => true, 'show_in_rest' => true, 'auth_callback' => function () { return current_user_can('manage_categories'); }));
}, 5);
add_action('admin_menu', function () {
    add_menu_page('Galerija', 'Galerija', 'edit_posts', 'rk-galerija', 'rk_galui_page', 'dashicons-format-gallery', 25);
    add_submenu_page('rk-galerija', 'Galerija', 'Valdymas', 'edit_posts', 'rk-galerija', 'rk_galui_page');
}, 20);
add_action('admin_init', function () {
    global $pagenow;
    $pt = isset($_GET['post_type']) ? $_GET['post_type'] : '';
    $tx = isset($_GET['taxonomy']) ? $_GET['taxonomy'] : '';
    if (($pagenow === 'edit.php' && $pt === 'rk_galerija') || ($pagenow === 'edit-tags.php' && $tx === 'rk_gal_kat') || ($pagenow === 'post-new.php' && $pt === 'rk_galerija')) {
        wp_safe_redirect(admin_url('admin.php?page=rk-galerija')); exit;
    }
});
add_action('admin_head', function () {
    $s = get_current_screen();
    if ($s && $s->id === 'toplevel_page_rk-galerija') echo '<style>.update-nag,.notice:not(.rkg-keep),#wpfooter{display:none!important}#wpbody-content{padding-bottom:0}</style>';
});
add_filter('register_post_type_args', function ($args, $type) {
    if ($type === 'rk_galerija') { $args['show_in_menu'] = false; }
    return $args;
}, 10, 2);
// isvalyti Elementor kesa puslapiams, kuriuose rodoma galerija (kad pakeitimai matytusi is karto)
function rk_galui_purge() {
    foreach (get_terms(array('taxonomy' => 'rk_gal_kat', 'hide_empty' => false)) as $t) { $p = (int) get_term_meta($t->term_id, 'rk_page', true); if ($p) delete_post_meta($p, '_elementor_element_cache'); }
    $g = get_page_by_path('galerija'); if ($g) delete_post_meta($g->ID, '_elementor_element_cache');
}
add_action('save_post_rk_galerija', 'rk_galui_purge'); add_action('deleted_post', 'rk_galui_purge'); add_action('trashed_post', 'rk_galui_purge'); add_action('untrashed_post', 'rk_galui_purge'); add_action('edited_rk_gal_kat', 'rk_galui_purge'); add_action('delete_rk_gal_kat', 'rk_galui_purge');
