 var q=S.q.toLowerCase();var list=S.items.filter(function(i){if(i.rk_gal_kat.indexOf(S.cat)<0)return false;var t=decode(i.title.rendered);if(q&&t.toLowerCase().indexOf(q)<0)return false;if(S.noempty&&t.trim()&&!/^darbu pavyzdys$/i.test(t.trim()))return false;return true;});S.list=list;$('#rkg-count').textContent=list.length+' nuotr.';$('#rkg-selall').checked=list.length>0&&list.every(function(i){return S.sel.has(i.id)});
