 list.forEach(function(it,idx){var c=document.createElement('div');c.className='rkg-card'+(S.sel.has(it.id)?' sel':'')+(S.newIds.has(it.id)?' new':'');c.draggable=true;c.dataset.id=it.id;var url=S.media[it.featured_media]||'';var cap=decode(it.title.rendered);var isEmpty=!cap.trim()||/^darbu pavyzdys$/i.test(cap.trim());
