  var ta=c.querySelector('textarea');ta.value=isEmpty?'':cap;var msg=c.querySelector('.msg');var t;ta.addEventListener('input',function(){clearTimeout(t);msg.textContent='Rašoma…';ta.classList.toggle('empty',!ta.value.trim());t=setTimeout(save,700)});ta.addEventListener('blur',function(){clearTimeout(t);save()});
