function render_sum(){var noCap=S.items.filter(function(i){var t=decode(i.title.rendered).trim();return !t||/^darbu pavyzdys$/i.test(t)}).length;$('#rkg-sum').innerHTML='<b>'+S.items.length+'</b> nuotr. · <b>'+S.cats.length+'</b> kategorijos'+(noCap?' · <span style="color:#c2410c">'+noCap+' be aprašymo</span>':' · visos su aprašymais ✓');}
async function move(list,from,to){if(to<0||to>=list.length)return;var m=list.splice(from,1)[0];list.splice(to,0,m);render();try{for(var i=0;i<list.length;i++){if(list[i].menu_order!==i+1){await api('wp/v2/rk_galerija/'+list[i].id,{method:'POST',body:JSON.stringify({menu_order:i+1})});list[i].menu_order=i+1;}}toast('Eiliškumas išsaugotas');}catch(e){toast('Klaida: '+e.message,1)}}
async function del(ids){var n=0;for(const id of ids){try{await api('wp/v2/rk_galerija/'+id,{method:'DELETE'});n++;}catch(e){}}S.sel.clear();bulk();await load();toast('Pašalinta: '+n+' nuotr.',0,{label:'Atšaukti',fn:async function(){for(const id of ids){try{await api('wp/v2/rk_galerija/'+id,{method:'POST',body:JSON.stringify({status:'publish'})})}catch(e){}}await load();toast('Grąžinta');}});}
