$('#rkg-bulk-x').onclick=function(){S.sel.clear();bulk();render()};$('#rkg-bulk-del').onclick=function(){if(!confirm('Pašalinti '+S.sel.size+' pažymėtas nuotraukas iš galerijos?'))return;del(Array.from(S.sel))};
$('#rkg-bulk-move').onclick=async function(){var to=+$('#rkg-bulk-cat').value;if(!to)return;var n=0;for(const id of S.sel){try{await api('wp/v2/rk_galerija/'+id,{method:'POST',body:JSON.stringify({rk_gal_kat:[to]})});n++;}catch(e){}}S.sel.clear();bulk();await load();toast('Perkelta: '+n+' nuotr.');};
$('#rkg-selall').onchange=function(){var on=this.checked;(S.list||[]).forEach(function(i){if(on)S.sel.add(i.id);else S.sel.delete(i.id)});bulk();render()};
$('#rkg-q').addEventListener('input',function(){S.q=this.value;render()});$('#rkg-noempty').onchange=function(){S.noempty=this.checked;render()};
