function lightbox(list,i){var m=$('#rkg-lb');if(!m){m=document.createElement('div');m.id='rkg-lb';m.className='rkg-lb';m.innerHTML='<button class="lb-x">✕</button><button class="lb-p">‹</button><button class="lb-n">›</button><figure><img><figcaption></figcaption></figure>';document.body.appendChild(m);m.querySelector('.lb-x').onclick=function(){m.classList.remove('on')};m.onclick=function(e){if(e.target===m)m.classList.remove('on')};document.addEventListener('keydown',function(e){if(!m.classList.contains('on'))return;if(e.key==='Escape')m.classList.remove('on');if(e.key==='ArrowRight')m._n();if(e.key==='ArrowLeft')m._p();});}
 function show(k){k=(k+list.length)%list.length;m._i=k;var it=list[k];m.querySelector('img').src=S.media[it.featured_media]||'';m.querySelector('figcaption').textContent=(k+1)+' / '+list.length+' · '+decode(it.title.rendered);}
