function shrink(f){return new Promise(function(res){if(!/^image\/(jpeg|png|webp)$/.test(f.type)||f.size<600*1024)return res(f);var img=new Image();var u=URL.createObjectURL(f);img.onload=function(){var MAX=2000,w=img.width,h=img.height;if(Math.max(w,h)<=MAX&&f.size<2.5*1024*1024){URL.revokeObjectURL(u);return res(f)}var k=Math.min(1,MAX/Math.max(w,h));var cv=document.createElement('canvas');cv.width=Math.round(w*k);cv.height=Math.round(h*k);cv.getContext('2d').drawImage(img,0,0,cv.width,cv.height);cv.toBlob(function(b){URL.revokeObjectURL(u);if(!b)return res(f);var nf=new File([b],f.name.replace(/\.[^.]+$/,'')+'.jpg',{type:'image/jpeg'});res(nf.size<f.size?nf:f)},'image/jpeg',.86)};img.onerror=function(){URL.revokeObjectURL(u);res(f)};img.src=u;});}
function capFrom(name){var c=name.replace(/\.[^.]+$/,'').replace(/[_-]+/g,' ').trim();return /^(img|dsc|image|photo|pxl|screenshot)[\s\d]*$/i.test(c)?'':c;}
async function up(files){if(!S.cat){toast('Pirmiausia sukurkite kategoriją',1);return}files=[].slice.call(files).filter(function(f){return /^image\//.test(f.type)||/\.(heic|heif)$/i.test(f.name)});if(!files.length){toast('Pasirinkite nuotraukų failus (JPG, PNG…)',1);return}
 var box=$('#rkg-up');box.innerHTML='';box.classList.add('on');var rows=files.map(function(f){var r=document.createElement('div');r.className='row';r.innerHTML='<img><span style="width:220px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">'+f.name+'</span><div class="bar"><i></i></div><span class="st">laukia</span>';box.appendChild(r);try{r.querySelector('img').src=URL.createObjectURL(f)}catch(e){}return r;});
 var max=S.items.reduce(function(m,i){return Math.max(m,i.menu_order||0)},0);var done=0,ok=0;var catId=S.cat;
 async function one(i){var f=files[i],r=rows[i],st=r.querySelector('.st'),bar=r.querySelector('.bar i');try{st.textContent='ruošiama';var g=await shrink(f);bar.style.width='30%';st.textContent='keliama';var fd=new FormData();fd.append('file',g,g.name);fd.append('title',capFrom(f.name)||'Darbu pavyzdys');var m=await new Promise(function(res,rej){var x=new XMLHttpRequest();x.open('POST',REST+'wp/v2/media');x.setRequestHeader('X-WP-Nonce',N);x.withCredentials=true;x.upload.onprogress=function(e){if(e.lengthComputable)bar.style.width=(30+Math.round(e.loaded/e.total*60))+'%'};x.onload=function(){x.status<300?res(JSON.parse(x.responseText)):rej(new Error(x.status))};x.onerror=function(){rej(new Error('tinklas'))};x.send(fd)});var p=await api('wp/v2/rk_galerija',{method:'POST',body:JSON.stringify({title:capFrom(f.name),status:'publish',featured_media:m.id,rk_gal_kat:[catId],menu_order:++max})});S.newIds.add(p.id);bar.style.width='100%';r.classList.add('ok');st.textContent='įkelta ✓';ok++;}catch(e){r.classList.add('err');st.textContent='klaida';bar.style.width='100%';bar.style.background='#fca5a5';}done++;}
 var q=files.map(function(_,i){return i});async function worker(){while(q.length){await one(q.shift())}}await Promise.all([worker(),worker(),worker()]);
 await load();toast(ok===files.length?'Įkelta: '+ok+' nuotr. Dabar įrašykite aprašymus.':'Įkelta '+ok+' iš '+files.length+' – kai kurių nepavyko',ok!==files.length);setTimeout(function(){box.classList.remove('on')},ok===files.length?2500:8000);var first=document.querySelector('.rkg-card.new');if(first)first.scrollIntoView({behavior:'smooth',block:'center'});}
