function openCat(c){S.editCat=c;$('#rkg-m-title').textContent=c?'Kategorijos nustatymai':'Nauja kategorija';$('#rkg-m-name').value=c?c.name:'';var s=$('#rkg-m-page');s.innerHTML='<option value="0">— nerodyti svetainėje —</option>';S.pages.forEach(function(p){if(p.slug==='galerija'||p.slug==='privatumo-politika')return;var o=document.createElement('option');o.value=p.id;o.textContent=p.title.rendered;if(c&&c.meta&&c.meta.rk_page==p.id)o.selected=true;s.appendChild(o)});$('#rkg-m-del').style.display=c?'':'none';$('#rkg-modal').classList.add('on');setTimeout(function(){$('#rkg-m-name').focus()},50);}
$('#rkg-cat-edit').onclick=function(){openCat(curCat()||null)};$('#rkg-cat-new').onclick=function(){openCat(null)};$('#rkg-m-cancel').onclick=function(){$('#rkg-modal').classList.remove('on')};$('#rkg-modal').addEventListener('click',function(e){if(e.target===this)this.classList.remove('on')});document.addEventListener('keydown',function(e){if(e.key==='Escape')$('#rkg-modal').classList.remove('on');if(e.key==='Enter'&&$('#rkg-modal').classList.contains('on')&&e.target.id==='rkg-m-name')$('#rkg-m-save').click()});
$('#rkg-m-save').onclick=async function(){var name=$('#rkg-m-name').value.trim();if(!name){toast('Įrašykite pavadinimą',1);return}var body={name:name,meta:{rk_page:+$('#rkg-m-page').value}};try{if(S.editCat){await api('wp/v2/rk_gal_kat/'+S.editCat.id,{method:'POST',body:JSON.stringify(body)})}else{var r=await api('wp/v2/rk_gal_kat',{method:'POST',body:JSON.stringify(body)});S.cat=r.id}$('#rkg-modal').classList.remove('on');toast('Kategorija išsaugota');await load();}catch(e){toast('Klaida: '+e.message,1)}};
$('#rkg-m-del').onclick=async function(){if(!S.editCat)return;if(!confirm('Ištrinti kategoriją „'+S.editCat.name+'“? Nuotraukos liks, bet nebebus rodomos svetainėje.'))return;try{await api('wp/v2/rk_gal_kat/'+S.editCat.id+'?force=true',{method:'DELETE'});$('#rkg-modal').classList.remove('on');S.cat=null;toast('Kategorija ištrinta');await load();}catch(e){toast('Klaida: '+e.message,1)}};
load().catch(function(e){toast('Nepavyko įkelti duomenų: '+e.message,1)});
